        ("What is the CSS specificity hierarchy order from highest to lowest?", "Inline styles > ID selectors > Class/Attribute/Pseudo-class > Element selectors", ["ID > Inline > Class > Element", "Element > Class > ID > Inline", "Class > ID > Inline > Element"], "Specificity order: Inline (1000) > ID (100) > Class/Pseudo-class (10) > Tag element (1)."),
        ("What CSS pseudo-class styles a hyperlink when a user hovers a pointer over it?", ":hover", [":active", ":focus", ":visited"], "The ':hover' pseudo-class triggers visual styles upon mouse cursor hover."),
        ("What CSS pseudo-class styles an interactive form input when it receives keyboard focus?", ":focus", [":hover", ":active", ":checked"], "The ':focus' pseudo-class applies when an element is active or selected by tab navigation."),
        ("What is the purpose of the responsive HTML viewport meta tag?", "Controls layout viewport scaling and width on mobile device screens", ["Loads CSS fonts", "Specifies SEO keywords", "Sets browser language"], "<meta name='viewport' content='width=device-width, initial-scale=1'> ensures proper mobile scaling."),
        ("What CSS media query rule applies styles only to screens narrower than 768px?", "@media (max-width: 767.98px)", ["@media (min-width: 768px)", "@media screen and (height: 768px)", "@screen-mobile"], "@media (max-width: ...) applies conditional CSS when viewport width is below specified threshold."),
        ("What does the 'rem' font unit stand for and measure in CSS?", "Root em (relative to the font-size of the root <html> element)", ["Relative element margin", "Raster pixel multiplier", "Resolution em"], "1 rem equals the font-size of the root element (typically 16px by default in browsers)."),
        ("What does the 'em' unit in CSS measure when styling font-size?", "Relative to the font-size of the element's direct parent", ["Relative to viewport width", "Exact screen pixels", "Root html font size"], "The 'em' unit scales relative to the immediate parent element's font size."),
        ("What does '100vh' represent in CSS units?", "100% of the browser viewport height", ["100 vector horizontal units", "100 pixels height", "100 visual headers"], "Viewport Height (vh): 1 vh equals 1% of the viewport's vertical visible height."),
        ("What does '100vw' represent in CSS units?", "100% of the browser viewport width", ["100 pixels width", "100 virtual words", "100 vector weights"], "Viewport Width (vw): 1 vw equals 1% of the viewport's horizontal visible width."),
        ("Which CSS property controls element stacking order along the imaginary 3D depth axis?", "z-index", ["layer-depth", "stack-order", "elevation"], "'z-index' determines layer stacking order for positioned elements (higher values sit on top)."),
        ("What is the effect of setting 'display: none' on an HTML element?", "Removes the element completely from document rendering and layout flow", ["Makes element invisible but preserves its space", "Lowers opacity to 0", "Disables clicks only"], "'display: none' removes the element from rendering; 'visibility: hidden' hides it while preserving space."),
        ("What CSS property rounds the corners of an element's outer border edge?", "border-radius", ["corner-curve", "border-style", "box-radius"], "'border-radius: 12px' curves box corners with circular or elliptical radii."),
        ("Which semantic HTML5 tag designates navigation links (menus, headers, sidebars)?", "<nav>", ["<menu>", "<links>", "<navbar>"], "The <nav> semantic tag specifies a section intended for site or page navigation links."),
